fn comment<T: Read>(lex: &mut YYLex<T>) {
    let mut c = lex.input();
    while c != b'*' && c != 0 {
        c = lex.input();
        if c == b'*' {
            while c == b'*' {
                c = lex.input();
            }
            if c == b'/' || c == 0 {
                return;
            }
        }
    }
}
